  ground_meat:{label:'Carne picada / hamburguesas',days:105,freeze:'Divide en raciones y separa las piezas para sacar solo las necesarias.',thaw:'Pasa a la nevera la noche anterior y cocina completamente.',after:'Cocina en 1–2 días después de descongelar.'},
  red_meat:{label:'Filetes, chuletas y asados',days:240,freeze:'Envuelve bien cada pieza para evitar quemaduras por frío.',thaw:'Descongela lentamente en la nevera.',after:'Utiliza en 3–5 días según la pieza.'},
  poultry:{label:'Pollo o pavo en piezas',days:270,freeze:'Congela por raciones y etiqueta la fecha.',thaw:'Pasa a la nevera con 24 horas de antelación; evita lavar el pollo crudo.',after:'Cocina en 1–2 días.'},
  poultry_whole:{label:'Pollo o pavo entero',days:365,freeze:'Protege bien toda la superficie y deja espacio para una congelación rápida.',thaw:'Necesita normalmente 1–2 días en la nevera según tamaño.',after:'Cocina en 1–2 días.'},
  fatty_fish:{label:'Pescado graso',days:75,freeze:'Seca, envuelve herméticamente y congela lo antes posible.',thaw:'Descongela en la nevera. Para consumo crudo aplica la prevención de anisakis.',after:'Consume en 1 día.'},
