  pizza:{label:'Pizza / quiche',days:60,direct:true,freeze:'Protege bien las porciones y etiqueta la fecha.',thaw:'Suele poder cocinarse directamente congelada; comprueba la receta o etiqueta.',after:'Consume tras cocinar.'},
